const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const geometry = ee.Geometry.Point(-69.0, -23.0); // A point in the high-altitude Atacama Desert
  const startDate = '2025-06-01';
  const endDate = '2025-07-31';

  // 2. Data Acquisition & Check
  let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(geometry)
    .filterDate(startDate, endDate);

  const initialSize = await collection.size().getInfo();
  if (initialSize === 0) {
    console.log("No Sentinel-2 SR images found for June-July 2025.");
    console.log("C1");
    return;
  }
  console.log(`Initial S2 images: ${initialSize}`);

  // Masking Function for Sentinel-2 SR
  function maskS2clouds(image) {
    const qa = image.select('SCL');
    // SCL values: 1=no_data, 2=saturated/defective, 3=dark_area_pixels, 4=cloud_shadow, 5=vegetation, 6=not_vegetated, 7=water, 8=unclassified, 9=medium_proba_clouds, 10=high_proba_clouds, 11=thin_cirrus, 12=snow_ice
    // We want to keep snow (11) for detection, so we mask out clouds (9, 10, 3, 4)
    const cloudMask = qa.eq(9).or(qa.eq(10)).or(qa.eq(3)).or(qa.eq(4)).not();
    return image.updateMask(cloudMask);
  }

  // Apply cloud mask but keep snow/ice for detection
  collection = collection.map(maskS2clouds);

  // Define snow pixel detection: SCL band value 11 (snow/ice)
  function detectSnow(image) {
    const snow = image.select('SCL').eq(11).rename('snow_pixels');
    return image.addBands(snow);
  }

  collection = collection.map(detectSnow);

  // Reduce collection to get a single image showing maximum snow presence
  const maxSnowImage = collection.select('snow_pixels').max();

  // If no images remain after filtering, maxSnowImage will be null or have no data.
  // Check if maxSnowImage is valid before proceeding.
  if (maxSnowImage === null || (await maxSnowImage.bandNames().getInfo()).length === 0) {
    console.log("No valid images after cloud masking, or no snow_pixels band generated.");
    console.log("C2");
    return;
  }

  // Calculate the sum of snow_pixels in the geometry.
  // We use a larger scale to avoid computation limits for general presence check.
  const snowPixelCount = await maxSnowImage.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: geometry.buffer(10000), // Buffer the point to cover a small area
    scale: 100, // Sentinel-2 resolution is 10m, but 100m for broader region sum.
    maxPixels: 1e9
  }).get('snow_pixels').getInfo();

  // 3. Validation & Final Answer
  if (snowPixelCount === null || isNaN(snowPixelCount)) {
    console.log("Calculation for snow pixel count failed.");
    console.log("C3");
  } else if (snowPixelCount > 0) {
    console.log(`Snow pixels detected within the region: ${snowPixelCount}`);
    console.log("A"); // Yes
  } else {
    console.log("No snow pixels detected within the region.");
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
